        {
            base.OnCreate();

            CreateRoot();

            resource   .OnCreate();
            renderers  .OnCreate();
            controls   .OnCreate();
            layouts    .OnCreate();
            animation  .OnCreate();
            eventSystem.OnCreate();

            dynamicAtlas.Init(Define.defaultDynamicAtlasSize.x, Define.defaultDynamicAtlasSize.y, 
                FreeRectChoiceHeuristic.RectBottomLeftRule);

            if(Define.muiCreateRenderLogin)
            {
                CreateRenderers();
            }
        }

        private void CreateRoot()
        {
            if (m_root == null)
            {
                m_root = new GameObject("MUI");
#if UNITY_EDITOR
                if(Application.isPlaying){
                    GameObject.DontDestroyOnLoad(m_root);
                }
#else
                GameObject.DontDestroyOnLoad(m_root);
#endif
                
            }

            if (m_rootFx == null)
            {
                m_rootFx = new GameObject("MUI_Fx");
                if (m_root != null)
                {
                    m_rootFx.AttachTo(m_root);
                }
            }
            
            SetGlobalAlpha(1.0f);
        }

        public GameObject GetFxRoot()
        {
            return m_rootFx;
        }

        public override void OnUpdate(float deltaTime)
        {
            base.OnUpdate(deltaTime);

            camera.OnUpdate(deltaTime);
            keywords.OnUpdate(deltaTime);
            eventSystem.OnUpdate(deltaTime);
