    "sourceCode": "        public override void OnUpdate(float deltaTime)
        {
            Timi.InjectProfiler.ProfilerUtil.BeginCpuSample(6);
            var armyMgr = MapManager.ArmyEntityManager;
            if (armyMgr == null)
            {
                Timi.InjectProfiler.ProfilerUtil.EndCpuSample();
                return;
            }

            var mapEffectMgr = MapManager.MapEntityEffectMgr;
            var mapEntityMgr = MapManager.MapEntityManager;
            var entityMgr = GameCore.DotsMgr.EntityMgr;

            UtilArmyProfiler.DoProfilerSampleBegin((int)UtilArmyProfiler.ArmySampleType.ViewLineMgr_OnUpdateChaserLine);
            // 刷新追击行军线线头位置 同时删除不在视野内目标的线头
            OnUpdateChaserLine(entityMgr, mapEntityMgr);
            UtilArmyProfiler.DoProfilerSampleEnd((int)UtilArmyProfiler.ArmySampleType.ViewLineMgr_OnUpdateChaserLine);

            // 更新行军线目标特效（1.删除已经没有行军线的特效 2.对于异步创建的目标，创建之后需要刷新一下行军线）
            OnUpdateLineEffect(mapEffectMgr);

            // 2.0端到端直线行军线
            UpdateStraightMoveLine();

            // 缩放层会删除Entity 需要动态调整特效状态 (只有己方行军线会显示目标特效）
            foreach (var item in m_targetToEffectDict)
            {
                var wrapperActive = false;
                var entity = mapEntityMgr.GetEntity(item.Key);
                if (entity != default)
                {
                    wrapperActive = true;
                    mapEffectMgr.SetPos(item.Value, (Vector3) UtilCommon.GetPosition(entity) + ArmyEntityConst.ArmyLineEffectOffset);

                    if (RenderPipelineConfig.ForceArmyDisable)
                    {
                        var relation = UtilRelationShip.GetRelation(entity);
                        wrapperActive = relation == RelationshipType.Self;
                    }
                }

                var wrapper = mapEffectMgr.GetWrapper(item.Value);
                wrapper?.SetActive(wrapperActive);
                // mapEntityMgr.SetScale(item.Value, entity != default ? 1 : 0);
            }

            if (m_touchUpEmptyEffectID != 0 && m_touchEffectDelayTime > 0)
            {
                m_touchEffectDelayTime -= deltaTime;
                if (m_touchEffectDelayTime <= 0)
                {
                    mapEffectMgr.StopEffect(m_touchUpEmptyEffectID);
                    m_touchUpEmptyEffectID = 0;
                }
            }

            foreach (var item in m_armyPredictDict.Keys)
            {
                RefreshPredictMoveLineStartPos(item);
            }

            // Refresh preview line start positions to follow entity movement
            foreach (var item in m_armyPreviewDict)
            {
                UtilArmyCtrl.RefreshArmyPreviewLineStartPos(item.Key);
            }

            ProcessPendingMoveLineQueue();

            UpdateEntityMoveLine();
            UpdateFinalPosEffect();

            Timi.InjectProfiler.ProfilerUtil.EndCpuSample();
        }",
